action.command:
node -e "
const file = JSON.parse(require('fs').readFileSync('/dev/stdin','utf8')).file || '';
const isApiCode = file.includes('/api/') || file.includes('_router.py') || file.includes('_service.py');
if (!isApiCode) process.exit(0);
const { execSync } = require('child_process');
const domain = file.match(/(\w+)_(router|service)\.py/);
const testPattern = domain ? 'backend/tests/**/*' + domain[1] + '*.py' : 'backend/tests/';
try {
  execSync('pytest ' + testPattern + ' -x -q', {cwd: process.env.WORKSPACE_ROOT || '.', stdio:'pipe'});
  console.log('Related unit tests passed for: ' + file);
} catch(e) { process.stderr.write(e.stdout ? e.stdout.toString() : e.message); process.exit(1); }
"
